const s = $('Stats admin').first().json;

const dateStr = new Date().toLocaleDateString('en-US', {
  weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

const HEADER = '#1a1a2e';
const ACCENT = '#457b9d';
const VERT   = '#2d6a4f';
const ROUGE  = '#c1121f';
const GRIS   = '#f8f9fa';

function ligne(label, valeur, couleur) {
  return `<tr>
    <td style="padding:8px 12px;font-size:14px;color:#444;border-bottom:1px solid #eee;">${label}</td>
    <td style="padding:8px 12px;font-size:16px;font-weight:bold;color:${couleur || '#222'};text-align:right;border-bottom:1px solid #eee;">${valeur}</td>
  </tr>`;
}

function section(titre, lignes) {
  return `
  <p style="margin:20px 0 6px 0;font-size:13px;font-weight:bold;color:${ACCENT};text-transform:uppercase;letter-spacing:1px;">${titre}</p>
  <table width="100%" cellpadding="0" cellspacing="0" style="border:1px solid #e0e0e0;border-radius:6px;background:#fff;">
    ${lignes}
  </table>`;
}

const html = `<!DOCTYPE html><html><body style="margin:0;padding:0;background:${GRIS};font-family:Arial,sans-serif;">
<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 16px;">
<table width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">

  <tr><td style="background:${HEADER};border-radius:10px 10px 0 0;padding:24px 28px;">
    <p style="margin:0;font-size:12px;color:#aaaacc;text-transform:uppercase;letter-spacing:2px;">Admin Intelligence Digest</p>
    <p style="margin:6px 0 0 0;font-size:22px;font-weight:bold;color:#fff;">🛠 News Monitor &mdash; ${dateStr}</p>
  </td></tr>

  <tr><td style="background:${GRIS};padding:16px 28px;">
    ${section('Articles (Past 24h)',
      ligne('Total Collected',      s.articles_total,      ACCENT) +
      ligne('Successfully Analyzed',s.articles_analyses,   VERT)   +
      ligne('Pending Analysis',     s.articles_en_attente,'#888') +
      ligne('Analysis Errors',      s.articles_erreurs,    s.articles_erreurs > 0 ? ROUGE : '#888')
    )}
    ${section('Newsletter Subscribers',
      ligne('Active Subscribers',   s.abonnes_actifs,      ACCENT) +
      ligne('New Today',            s.nouveaux_abonnes,    s.nouveaux_abonnes > 0 ? VERT : '#888') +
      ligne('Unsubscribes',         s.desabonnements,      s.desabonnements > 0 ? ROUGE : '#888')
    )}
    ${section('Newsletter Dispatches (Past 24h)',
      ligne('Newsletters Sent',     s.newsletters_envoyees, VERT) +
      ligne('Delivery Errors',      s.newsletters_erreurs,  s.newsletters_erreurs > 0 ? ROUGE : '#888')
    )}
    ${section('Email Bot Commands (Past 24h)',
      ligne('Commands Handled',     s.commandes_traitees,  VERT) +
      ligne('Ollama Parser Errors', s.commandes_erreurs,   s.commandes_erreurs > 0 ? ROUGE : '#888')
    )}
  </td></tr>

  <tr><td style="background:${HEADER};border-radius:0 0 10px 10px;padding:14px 28px;">
    <p style="margin:0;font-size:11px;color:#666688;">Admin: http://localhost:8090 &nbsp;&bull;&nbsp; n8n: http://localhost:5678</p>
  </td></tr>

</table></td></tr></table>
</body></html>`;

const alertes = [];
if (s.articles_erreurs > 0)      alertes.push(`${s.articles_erreurs} article errors`);
if (s.newsletters_erreurs > 0)   alertes.push(`${s.newsletters_erreurs} dispatch errors`);
if (s.commandes_erreurs > 0)     alertes.push(`${s.commandes_erreurs} parser errors`);

const sujet = alertes.length > 0
  ? `⚠️ News Monitor ${dateStr} — ${alertes.join(', ')}`
  : `✅ News Monitor ${dateStr} — ${s.articles_analyses} articles · ${s.abonnes_actifs} subscribers`;

return [{ json: { sujet, html } }];
